const MAX_ITER = 10;

const webhookJson = $('Webhook Trigger').item.json;
const inp         = $input.first().json;

const body = webhookJson.body || inp.body || inp;

const inputText = (body.user_prompt || body.prompt || body.question || '').trim();
if (!inputText) {
  throw new Error('No input found. Send: { "user_prompt": "your question here" }');
}

const startMs   = inp.start_time_ms || Date.now();
const tokenEst  = Math.ceil(inputText.length / 4);

const g = $getWorkflowStaticData('global');
g.react_state = {
  input_text:           inputText,
  trajectory:           [],
  max_iterations:       MAX_ITER,
  start_time_ms:        startMs,
  input_token_estimate: tokenEst
};

return [{ json: {
  input_text:           inputText,
  max_iterations:       MAX_ITER,
  start_time_ms:        startMs,
  input_token_estimate: tokenEst
} }];

const init = $input.first().json;
const MAX  = init.max_iterations || 10;
return Array.from({ length: MAX }, (_, i) => ({
  json: {
    iteration:            i + 1,
    input_text:           init.input_text,
    start_time_ms:        init.start_time_ms,
    input_token_estimate: init.input_token_estimate
  }
}));

const slot  = $input.first().json;
const g     = $getWorkflowStaticData('global');
const state = g.react_state || {};
const traj  = state.trajectory || [];
const hopsLeft = (state.max_iterations || 10) - slot.iteration;

let trajectoryText = 'No steps taken yet. Begin your reasoning now.';
if (traj.length > 0) {
  trajectoryText = traj.map((s, i) =>
    'Step ' + (i+1) + ':' +
    ' Thought: ' + s.thought +
    ' | Action: ' + s.action +
    ' | Input: '  + s.action_input +
    (s.observation ? ' | Observation: ' + s.observation : '')
  ).join(' --- ');
}

const finalNote =
  hopsLeft <= 0
    ? ' FINAL STEP: You MUST output action="final_answer" now. Compile all observations into a complete answer. Do NOT call any tool.'
  : hopsLeft <= 2
    ? ' WARNING: Only ' + hopsLeft + ' step(s) remaining. If you have enough information, output final_answer NOW.'
    : '';

const promptText =
'You are a ReAct (Reason + Act) agent. Solve any question step by step.' +
' TOOL RULES:' +
' Use "wikipedia" to look up facts, definitions or events you are uncertain about.' +
' Use "calculator" for arithmetic - ONE expression per call, no commas in numbers.' +
' Use "datetime" for anything involving dates, times, timezones, countdowns or scheduling.' +
' For all other knowledge answer directly in final_answer.' +
' Output final_answer as soon as you have enough information.' +
' Available tools:' +
' "wikipedia" - looks up a topic on Wikipedia. action_input: short search term (2-5 words).' +
' "calculator" - evaluates one math expression. action_input: e.g. "1000*(1.085^2)-1000".' +
' "datetime" - answers date/time/timezone questions. action_input: plain-language question or date.' +
' Question: ' + state.input_text +
' Previous steps: ' + trajectoryText + finalNote +
' Decide your NEXT single step. Output ONLY valid JSON, no markdown:' +
' {"thought":"<reasoning>","action":"<wikipedia|calculator|datetime|final_answer>","action_input":"<single input or empty>","final_answer":"<answer if final_answer else empty>"}';

return [{ json: {
  iteration:            slot.iteration,
  prompt_text:          promptText,
  input_text:           state.input_text,
  start_time_ms:        state.start_time_ms,
  input_token_estimate: state.input_token_estimate,
  hops_remaining:       hopsLeft,
  max_iterations:       state.max_iterations || 10,
  trajectory_length:    traj.length
} }];

// chainLlm only passes through {text}, so we recover iteration from upstream
const iteration = $('Prepare ReAct Context').item.json.iteration;
const g      = $getWorkflowStaticData('global');
const state  = g.react_state || {};
const traj   = state.trajectory || [];

const raw    = ($input.first().json.text || $input.first().json.response || '').trim();
const VALID  = ['calculator','wikipedia','datetime','final_answer'];

let parsed;
try {
  // Robust extraction: find the first complete {...} JSON object in the output
  // This handles LLM output that has prose before/after the JSON
  const jsonMatch = raw.match(/\{[\s\S]*\}/);
  if (!jsonMatch) throw new Error('No JSON object found in LLM response');
  parsed = JSON.parse(jsonMatch[0]);
} catch(e) {
  parsed = {
    thought:      'Parse error: ' + e.message,
    action:       'final_answer',
    action_input: '',
    final_answer: raw
  };
}

if (!VALID.includes(parsed.action)) parsed.action = 'final_answer';

const step = {
  step:           iteration,
  thought:        parsed.thought      || '',
  action:         parsed.action,
  action_input:   parsed.action_input || '',
  final_answer:   parsed.final_answer || '',
  observation:    '',
  token_estimate: Math.ceil((parsed.thought || '').length / 4) +
                  Math.ceil((parsed.final_answer || '').length / 4)
};
traj.push(step);
g.react_state = { ...state, trajectory: traj };

const isFinalAnswer = parsed.action === 'final_answer';
const capReached    = iteration >= (state.max_iterations || 10);
const isDone        = isFinalAnswer || capReached;
const termReason    = capReached && !isFinalAnswer ? 'max_iterations_safety_cap' : 'agent_reached_final_answer';

// Reconstruct full context — chainLlm drops all input fields
return [{ json: {
  iteration:            iteration,
  input_text:           state.input_text,
  start_time_ms:        state.start_time_ms,
  input_token_estimate: state.input_token_estimate,
  action:               parsed.action,
  action_input:         parsed.action_input || '',
  final_answer:         parsed.final_answer || '',
  is_done:              isDone,
  termination_reason:   termReason
} }];

const d   = $input.first().json;
const g   = $getWorkflowStaticData('global');
const state = g.react_state || {};
const traj  = state.trajectory || [];

const finalStep = [...traj].reverse().find(s => s.action === 'final_answer');
const finalAns  = finalStep ? finalStep.final_answer : '(no final answer — safety cap triggered)';

const toolsUsed = traj.filter(s => s.action !== 'final_answer').map(s => s.tool_used || s.action);
const unique    = [...new Set(toolsUsed)];

return [{ json: {
  input_text:         state.input_text,
  final_answer:       finalAns,
  trajectory:         traj,
  total_steps:        traj.length,
  tools_used:         toolsUsed,
  unique_tools:       unique,
  tool_calls_count:   toolsUsed.length,
  termination_reason: d.termination_reason || 'unknown',
  start_time_ms:      state.start_time_ms,
  input_token_estimate: state.input_token_estimate
} }];

const endMs  = Date.now();
const c      = $input.first().json;
const latMs  = endMs - c.start_time_ms;
const latSec = parseFloat((latMs / 1000).toFixed(2));

const totalSteps  = c.total_steps || 0;
const llmCallsMax = 10;

const inpTok   = c.input_token_estimate || 0;
const agentTok = (c.trajectory || []).reduce((s,t) => s + (t.token_estimate || 0), 0);
const totalTok = inpTok + agentTok;

return [{ json: {

  user_prompt:  c.input_text,
  final_answer: c.final_answer,

  metadata: {
    pattern:          'ReAct — Reason and Act',
    pattern_category: 'Single-Agent Reasoning Pattern',
    run_timestamp:    new Date().toISOString(),
    model:            'qwen2.5:14b',
    model_provider:   'Ollama (local)',
    latency_ms:       latMs,
    latency_seconds:  latSec,
    llm_calls_actual: totalSteps,
    llm_calls_max:    llmCallsMax,
    token_usage: {
      total_input_tokens:  inpTok,
      total_output_tokens: agentTok,
      total_tokens:        totalTok
    },
    status:             'completed',
    termination_reason: c.termination_reason || 'unknown'
  },

  execution_trace: {
    trajectory: (c.trajectory || []).map(t => ({
      step:           t.step,
      thought:        t.thought,
      action:         t.action,
      action_input:   t.action_input,
      observation:    t.observation || (t.action === 'final_answer' ? '(final answer — no tool called)' : ''),
      tool_used:      t.tool_used   || (t.action !== 'final_answer' ? t.action : 'none'),
      final_answer:   t.action === 'final_answer' ? t.final_answer : '',
      token_estimate: t.token_estimate || 0
    })),

    react_summary: {
      total_steps:        totalSteps,
      tool_calls_count:   c.tool_calls_count,
      unique_tools_used:  c.unique_tools,
      tools_sequence:     c.tools_used,
      exited_early:       totalSteps < llmCallsMax,
      termination_reason: c.termination_reason
    },

    structural_properties: {
      pattern_category:   'Single-Agent Reasoning Pattern',
      agent_count:        1,
      orchestration_type: 'self-directed — single agent decides all tool calls and termination autonomously',
      tool_execution:     'specialist AI sub-agents (Calculator, Wikipedia, DateTime) — each is an agent node with its own LLM and native tool, no intermediate code nodes',
      transparency:       'full trajectory (thought + action + observation) preserved per step',
      loop_mechanism:     'splitInBatches with loop-back from Format Observation',
      termination_logic:  'agent outputs action=final_answer (AI-driven) OR step >= 10 (safety cap)',
      state_passing:      "$getWorkflowStaticData('global').react_state carries full trajectory between iterations",
      max_iterations:     llmCallsMax,
      actual_steps:       totalSteps
    },

    llm_limitation: 'Token counts are character-length estimates (chars / 4). The Ollama node does not return native token usage data.'
  }

} }];

const d     = $input.first().json;
const g     = $getWorkflowStaticData('global');
const state = g.react_state || {};
const traj  = state.trajectory || [];

if (traj.length > 0) {
  traj[traj.length - 1].observation = d.observation || '';
  traj[traj.length - 1].tool_used   = d.tool_used   || '';
}
g.react_state = { ...state, trajectory: traj };

return [{ json: {
  iteration:            d.iteration,
  input_text:           d.input_text  || state.input_text,
  start_time_ms:        d.start_time_ms || state.start_time_ms,
  input_token_estimate: d.input_token_estimate || state.input_token_estimate,
  last_observation:     d.observation,
  last_tool:            d.tool_used
} }];

const input = (query || 'today').trim().toLowerCase();
try {
  const now      = new Date();
  const DAYS     = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
  const MONTHS   = ['January','February','March','April','May','June','July','August','September','October','November','December'];
  function parseDate(s) { const d = new Date(s); if (isNaN(d)) throw new Error('Invalid date: "' + s + '"'); return d; }
  function diffDays(a, b) { return Math.round((b - a) / 86400000); }
  function fmt(dt) { return dt.toISOString().split('T')[0] + ' (' + DAYS[dt.getDay()] + ')'; }
  let result;
  if (['today','now','current date','current_date'].includes(input)) {
    result = 'Today is ' + fmt(now) + ', ' + MONTHS[now.getMonth()] + ' ' + now.getDate() + ', ' + now.getFullYear() + '.';
  } else if (input.startsWith('days_until:')) {
    const t = parseDate(input.slice(11));
    result  = 'Days until ' + fmt(t) + ': ' + diffDays(now, t) + ' day(s).';
  } else if (input.startsWith('days_between:')) {
    const parts = input.slice(13).split(':');
    result = 'Days between ' + parts[0] + ' and ' + parts[1] + ': ' + Math.abs(diffDays(parseDate(parts[0]), parseDate(parts[1]))) + ' day(s).';
  } else if (input.startsWith('add_days:')) {
    const parts = input.slice(9).split(':');
    const res   = new Date(parseDate(parts[0]).getTime() + parseInt(parts[1]) * 86400000);
    result = parts[0] + ' + ' + parts[1] + ' days = ' + fmt(res) + '.';
  } else if (input.startsWith('day_of_week:')) {
    const t = parseDate(input.slice(12)); result = t.toISOString().split('T')[0] + ' is a ' + DAYS[t.getDay()] + '.';
  } else {
    try { const t = parseDate(input); result = fmt(t) + ' — ' + diffDays(now, t) + ' day(s) from today.'; }
    catch(_) { result = 'Supported formats: "today" | "days_until:YYYY-MM-DD" | "days_between:DATE1:DATE2" | "add_days:DATE:N" | "day_of_week:YYYY-MM-DD"'; }
  }
  return result;
} catch(e) { return 'DateTime error: ' + e.message; }

const q = encodeURIComponent((query || '').trim());
if (!q) return 'No search term provided.';

const searchUrl =
  'https://en.wikipedia.org/w/api.php?action=query&list=search' +
  '&srsearch=' + q + '&format=json&srlimit=2&utf8=1&origin=*';

try {
  const searchResp = await fetch(searchUrl);
  const searchData = await searchResp.json();
  const hits = (searchData.query || {}).search || [];
  if (!hits.length) return 'No Wikipedia results found for: ' + query;

  // Fetch the intro extract of the top result
  const topTitle   = encodeURIComponent(hits[0].title);
  const extractUrl =
    'https://en.wikipedia.org/w/api.php?action=query&prop=extracts' +
    '&exintro=true&explaintext=true&titles=' + topTitle +
    '&format=json&origin=*';

  const extractResp = await fetch(extractUrl);
  const extractData = await extractResp.json();
  const pages = Object.values((extractData.query || {}).pages || {});
  if (!pages.length) return 'Wikipedia: ' + hits[0].title + ' — ' + hits[0].snippet.replace(/<[^>]+>/g,'');

  const page    = pages[0];
  const extract = (page.extract || '').slice(0, 800).trim();
  return 'Wikipedia – ' + page.title + ':\n' + extract;
} catch(e) {
  return 'Wikipedia lookup failed: ' + e.message;
}
